"""FM-16Z: Cartesian products, arguments, angle units and root verification."""
import sympy as s
from calibration_bank import LEVELS,L
x,h,k=s.symbols('x h k',real=True); I=s.I; pi=s.pi
PATHS={'cartesian-product':'CPX.arithmetic.multiply','argument-range':'CPX.polar.argument','angle-units':'CPX.radians.convert','verify-roots':'CPX.cubic-quartic.verify'}
RATIONALES={
'cartesian-product':['Reduce an integer power of i.','Diagnose failure to replace i squared by -1.','Expand two Cartesian factors.','Multiply three factors and simplify.','Recover two unknown real components from a specified product.','Classify a prescribed real product under an additional slope constraint, including the zero-product case.'],
'argument-range':['Identify a positive-axis angle.','Distinguish arctangent from quadrant-correct argument.','Determine exact argument in a specified range.','Find the argument of a translated displacement in a different range.','Reconstruct a point from its argument and a specified real coordinate.','Classify argument of a parameter-dependent point with quadrant changes and the origin exception.'],
'angle-units':['Convert a familiar positive degree angle.','Correct a reversed degree-radian conversion.','Convert signed rational multiples of pi to degrees.','Combine angles given in different units and express in both units.','Recover an integer rotation count from a specified mixed-unit interval.','Compare mixed-unit congruence conditions under a half-angle restriction and prove completeness.'],
'verify-roots':['Verify a supplied root by substitution.','Reject a root list with a duplicated simple root.','Check a complete cubic root list by multiplying factors.','Determine multiplicities of supplied quartic roots by exact factorisation.','Verify a candidate list against a missing coefficient, identifying a wrong multiplicity.','Compare entire proposed root lists with a two-parameter polynomial and identify necessary and sufficient coefficient conditions.']}

def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown cell')
 a,b,d=map(s.Integer,(v+1,v+3,3*v+5)); z=a+b*I; w=d-a*I
 if path=='cartesian-product':
  if l==1:
   n=4*d+v;f=[I**n];q=f'Use the cycle of powers of i to simplify i to the power {n}.';ans=L(f[0]);steps=[f'Divide {n} by 4; the remainder is {n%4}. Since i to the fourth power is 1, the result is {ans}.'];hint=['Reduce the exponent modulo four.'];mist='Using a cycle of two instead of four.'
  elif l==2:
   f=[-a*b];q=f'A student states that ({a}i)({b}i)={a*b}. Correct the product and explain the sign.';ans=L(f[0]);steps=[f'Multiply the real coefficients to obtain {a*b} times i squared.',f'As i squared is -1, the result is {ans}.'];hint=['What is i squared?'];mist='Treating i squared as positive one.'
  elif l==3:
   f=[s.expand(z*w)];q=f'Expand {L(z)} times {L(w)} and write the result in Cartesian form.';ans=L(f[0]);steps=[f'Expand the four terms: {a*d}, {-a*a}i, {b*d}i and {-a*b} times i squared.',f'Use i squared = -1 and collect real and imaginary terms: {ans}.'];hint=['Multiply every term in the first bracket by every term in the second.'];mist='Omitting the product of imaginary terms.'
  elif l==4:
   u=1+I;f=[s.expand(z*w),s.expand(z*w*u)];q=f'Calculate the Cartesian product of the three numbers {L(z)}, {L(w)} and 1+i. Show an intermediate product.';ans=L(f[1]);steps=[f'The first two factors multiply to {L(f[0])}.',f'Multiplying by 1+i changes a number R+Si into (R-S)+(R+S)i, giving {ans}.'];hint=['Collect terms after the first multiplication.'];mist='Expanding three brackets without reducing i squared.'
  elif l==5:
   target=s.expand(z*w);f=[d,-a];q=f'Find real x,y such that {L(z)} multiplied by x+iy equals {L(target)}. Use Cartesian expansion and prove uniqueness.';ans=f'x={d}, y={-a}.';steps=[f'Equating components gives {a}x-{b}y={s.re(target)} and {b}x+{a}y={s.im(target)}.',f'The determinant is {a*a+b*b}, which is nonzero.',f'Solving gives {ans} Substitution verifies the product.'];hint=['Compare real and imaginary components.'];mist='Equating just one component.'
  else:
   q=f'For each real h find all real x,y such that the product of {L(z)} and x+iy is the real number h. Then impose y=kx for real k and classify all solutions for every pair (h,k).';ans=f'Without the last constraint x={L(a*h/(a*a+b*b))}, y={L(-b*h/(a*a+b*b))}. With y=kx, h=0 gives x=y=0 for every k; h nonzero requires k={L(-b/a)}, giving the same unique solution; otherwise none.';f=[a/(a*a+b*b),-b/(a*a+b*b),-b/a];steps=[f'Expansion forces {a}x-{b}y=h and {b}x+{a}y=0.',f'The determinant {a*a+b*b} is positive; solve to obtain x={L(a*h/(a*a+b*b))}, y={L(-b*h/(a*a+b*b))}.',f'If h=0 both components vanish and every k is allowed. If h is nonzero, x is nonzero and dividing y by x forces k={L(-b/a)}.', 'Conversely these values satisfy both the product and the extra constraint; there are no other possibilities.'];hint=['Compare components before dividing by x.'];mist='Dividing by x and losing the zero solution.'
 elif path=='argument-range':
  angles=[pi/6,pi/4,pi/3]; theta=angles[v-1]; t=s.tan(theta)
  if l==1:
   f=[0];q=f'Determine the principal argument of the positive real number {d}.';ans='0 radians.';steps=['The point is on the positive real axis, so its angle measured from that axis is zero.'];hint=['Locate the point on the real axis.'];mist='Confusing modulus with argument.'
  elif l==2:
   f=[-pi+theta];Z=-a-I*a*t;q=f'A student uses the inverse tangent of Im(z)/Re(z) as the principal argument of {L(Z)}. Give the correct principal argument and explain the quadrant.';ans=L(f[0]);steps=[f'The ratio of imaginary to real component is {L(t)}, whose inverse tangent is {L(theta)}.',f'Both components are negative, so the principal angle is {L(theta)} minus pi, giving {ans}.'];hint=['Identify the quadrant before choosing the angle.'];mist='Using arctangent without quadrant correction.'
  elif l==3:
   f=[pi-theta];Z=-a+I*a*t;q=f'Determine the exact argument of {L(Z)} in the interval (-pi,pi].';ans=L(f[0]);steps=[f'The reference angle is {L(theta)} from the component ratio.',f'The point is in quadrant II, so subtract the reference angle from pi: {ans}.'];hint=['Use the positive acute reference angle.'];mist='Reporting a negative quadrant-IV angle.'
  elif l==4:
   f=[2*pi-theta]; A=d+b*I;B=A+a-I*a*t;q=f'Points A and B represent {L(A)} and {L(B)}. Find the argument of the displacement from A to B in [0,2pi).';ans=L(f[0]);steps=[f'Subtract A from B: {L(s.expand(B-A))}.',f'The displacement is in quadrant IV; its principal angle is {L(-theta)}.',f'Adding 2pi gives {ans} in the requested interval.'];hint=['Subtract the starting point, not the endpoint.'];mist='Using the absolute position B instead of the displacement.'
  elif l==5:
   f=[-d-I*d*t];q=f'A complex number has real part {-d} and principal argument {L(theta-pi)}. Determine it exactly and justify that the ray condition holds.';ans=L(f[0]);steps=[f'Its imaginary part equals the real part times the tangent of the angle: {L(-d*t)}.',f'Both coordinates are negative, so the point is in quadrant III and has the required principal argument. Hence z={ans}.'];hint=['Use the ray rather than the full supporting line.'];mist='Taking the positive imaginary part.'
  else:
   q=f'For every real h determine the principal arguments of {L(h+I*h*t)} and {L(h-I*h*t)}. Explain what happens at h=0.';f=[theta,theta-pi,-theta,pi-theta];ans=f'h>0: arg(z)={L(theta)}, arg(u)={L(-theta)}; h<0: arg(z)={L(theta-pi)}, arg(u)={L(pi-theta)}; h=0: both undefined.';steps=[f'For positive h the real component is positive and the reference angle is {L(theta)}; the imaginary components have opposite signs.',f'For negative h each point is rotated by pi relative to its positive-h ray. Normalize into (-pi,pi]: z has argument {L(theta-pi)} and u has argument {L(pi-theta)}.', 'At h=0 both numbers are zero, whose argument is undefined. The three sign cases cover all real h.'];hint=['Separate positive, negative and zero h.'];mist='Cancelling h in the tangent ratio and missing the quadrant reversal.'
 elif path=='angle-units':
  if l==1:
   D=30*a;f=[D*pi/180];q=f'Convert {D} degrees into exact radians.';ans=L(f[0]);steps=[f'Multiply by pi/180: {ans}.'];hint=['180 degrees equals pi radians.'];mist='Multiplying by 180/pi.'
  elif l==2:
   A=pi/(2*a);f=[90/a];q=f'A student converts {L(A)} radians to degrees by multiplying by pi/180. Give the correct exact degree measure.';ans=f'{L(f[0])} degrees.';steps=['Radians to degrees requires multiplying by 180/pi.',f'The pi cancels, giving {ans}'];hint=['Choose the factor that cancels radians.'];mist='Using the degree-to-radian conversion backwards.'
  elif l==3:
   A=-b*pi/a;f=[-180*b/a];q=f'Convert the signed angle {L(A)} radians into degrees without normalizing it.';ans=f'{L(f[0])} degrees.';steps=[f'Multiply by 180/pi, retaining the negative sign: {ans}'];hint=['Do not add full turns.'];mist='Changing the angle to its principal representative.'
  elif l==4:
   D=45*b;A=-pi/a;f=[D-180/a,(D-180/a)*pi/180];q=f'A rotation of {D} degrees is followed by {L(A)} radians. Express the net signed rotation in exact degrees and radians.';ans=f'{L(f[0])} degrees, {L(f[1])} radians.';steps=[f'The second rotation is {L(-180/a)} degrees.',f'Add the signed angles to obtain {L(f[0])} degrees.',f'Convert the net angle to radians: {L(f[1])}.'];hint=['Use one common unit before addition.'];mist='Adding numerical measures with different units.'
  elif l==5:
   D=30*a;f=[b,b+1];q=f'Find every integer n for which the angle {D}+360n degrees lies in the interval from {L(2*b*pi)} radians (inclusive) to {L(2*(b+2)*pi)} radians (exclusive).';ans=f'n={b} or {b+1}.';steps=[f'The bounds become {360*b} and {360*(b+2)} degrees.',f'Solve {360*b} <= {D}+360n < {360*(b+2)}. Since 0<{D}<360, the only integers are {b}, {b+1}.'];hint=['Convert both bounds to degrees.'];mist='Including an integer outside the half-open interval.'
  else:
   D=30*a;q=f'An angle T degrees satisfies two conditions: T is congruent to {D} degrees modulo 360, and half of T is congruent to {L(D*pi/360)} radians modulo pi. Find every T in the interval [{L(-pi)}, {L(5*pi)}] when the interval endpoints are interpreted in radians. Then impose that T/2 is congruent to the same angle modulo 2pi instead.';f=[D,D+360,D+720,D,D+720];ans=f'First conditions: {D}, {D+360}, {D+720} degrees. With the stricter second congruence: {D}, {D+720} degrees.';steps=[f'Convert the interval to [-180,900] degrees. The first congruence gives T={D}+360n for integer n.',f'The half-angle condition modulo pi becomes T/2 congruent to {D/2} degrees modulo 180, which is automatic for all integer n.',f'The interval admits n=0,1,2, giving {D}, {D+360}, {D+720} degrees; n=-1 is below -180 and n=3 is above 900.',f'Changing the half-angle modulus to 2pi makes it 360 degrees, so 180n must be a multiple of 360. Thus n is even, leaving {D} and {D+720} degrees.'];hint=['Convert the congruence moduli as well as the angle values.'];mist='Treating a half-angle congruence as having the same period as the original.'
 else:
  F=(x-a)**2+b*b;G=s.expand((x+d)*F);R=s.expand(F*(x+d)**2)
  if l==1:
   f=[0];q=f'Verify by substitution that {-d} is a root of {L(G)}=0.';ans='Yes; the value is zero.';steps=[f'Substitute x={-d} into the expanded polynomial: {L(G.subs(x,-d))}.', 'The value is zero, so the number is a root.'];hint=['Evaluate the polynomial at the proposed root.'];mist='Checking a coefficient rather than evaluating the polynomial.'
  elif l==2:
   f=[False,1];q=f'A student lists {-d}, {-d}, {L(z)} as the three roots of {L(G)}=0, counting multiplicity. Is the list correct? State the multiplicity of {-d}.';ans=f'No; {-d} is simple and the missing root is {L(s.conjugate(z))}.';steps=[f'Factorisation is (x+{d}) times {L(s.expand(F))}.',f'The quadratic is nonzero at {-d}, since its value is {(d+a)**2+b*b}. Hence the real root occurs once, and both conjugate roots must occur.'];hint=['Check the multiplicity as well as the conjugate pair.'];mist='Assuming a repeated entry represents a repeated root.'
  elif l==3:
   f=[-d,s.conjugate(z),z];q=f'Verify that {-d}, {L(s.conjugate(z))} and {L(z)} are the complete root list of {L(G)}=0 by multiplying their monic linear factors.';ans='The list is complete; each root is simple.';steps=[f'The conjugate factors multiply to {L(s.expand(F))}.',f'Multiplying by x+{d} yields {L(G)}, the original monic cubic.', 'There are three distinct factors of degree one, accounting for the whole polynomial.'];hint=['Pair the conjugate factors first.'];mist='Substituting one root and assuming completeness.'
  elif l==4:
   f=[-d,2,s.conjugate(z),1,z,1];q=f'For {L(R)}=0, verify the multiplicity of each proposed root {-d}, {L(s.conjugate(z))}, {L(z)} by factorisation.';ans=f'{-d} has multiplicity 2; the conjugate roots each have multiplicity 1.';steps=[f'The polynomial factors as (x+{d}) squared times {L(s.expand(F))}; expanding gives {L(R)}.',f'The quadratic has the distinct roots {L(s.conjugate(z))}, {L(z)} and is nonzero at {-d}.',ans];hint=['Check that the quadratic does not also vanish at the real root.'];mist='Ignoring the repeated linear factor.'
  elif l==5:
   P=R-R.subs(x,0)+k;f=[R.subs(x,0),False,2];q=f'The quartic {L(P)} has root {L(z)}. Find k and assess the claimed complete list {-d}, {L(z)}, {L(z)}, {L(s.conjugate(z))}. Correct its multiplicities.';ans=f'k={R.subs(x,0)}; the list is wrong: {-d} twice, each conjugate once.';steps=[f'Evaluation at the supplied root gives k-{R.subs(x,0)}=0, so k={R.subs(x,0)}.',f'With that constant the polynomial equals (x+{d}) squared times {L(s.expand(F))}.',f'The quadratic is nonzero at {-d} and has two distinct non-real roots. Therefore the real root is double, not the supplied non-real root.'];hint=['Recover the constant first and verify the entire factorisation.'];mist='Accepting a list because every listed value is a root.'
  else:
   P=s.expand(F*(x*x+h*x+k));f=[2*d,d*d,-2*a,a*a+b*b];q=f'For real h,k consider the monic quartic {L(P)}. Candidate list A is {L(z)}, {L(s.conjugate(z))}, {-d}, {-d}. Candidate list B is {L(z)}, {L(s.conjugate(z))}, {L(z)}, {L(s.conjugate(z))}. Both lists count multiplicity. Find all parameter pairs for which either list is complete, prove that the lists cannot both be correct, and explain why checking only the two non-real roots cannot distinguish them.';ans=f'List A exactly when (h,k)=({2*d},{d*d}); list B exactly when (h,k)=({-2*a},{a*a+b*b}). These pairs are distinct; both non-real roots occur for every parameter pair.';steps=[f'Both lists include the conjugate pair, whose monic factor is {L(s.expand(F))}. The actual quartic contains that factor for every h,k.',f'List A requires the other monic quadratic to be (x+{d}) squared, or {L(s.expand((x+d)**2))}; coefficient comparison gives h={2*d}, k={d*d}.',f'List B requires the other quadratic to equal {L(s.expand(F))}; hence h={-2*a}, k={a*a+b*b}.',f'These pairs differ because {2*d} is positive and {-2*a} is negative. Conversely both coefficient matches reproduce the entire quartic, so all multiplicities and all roots are verified. Checking only the common conjugate roots gives no information about h,k.'];hint=['Construct the monic polynomial for each full root list, then cancel the common factor.'];mist='Checking root values without checking multiplicities or comparing the complete polynomial.'

 return dict(path=path,focus_skill=PATHS[path],tier=l,variant=v,assessment_role='prerequisite_bridge' if l==1 else 'concept_diagnostic' if l==2 else 'direct_focus_task',question_latex=q,final_answer_latex=ans,worked_solution_latex=steps,progressive_hints=hint,rubric=[dict(marks=1,criterion=e) for e in steps],facts=[e if type(e) is bool else str(e) for e in f],likely_mistake=mist,origin='original',examination_source=None,difficulty_status='editorial_design_teacher_pending',demand_rationale=RATIONALES[path][l-1])
